<template>
<div class="pg"><div class="hd"><h2>🎮 强化学习</h2><el-button type="primary" @click="showTrain=true">+ 新建RL任务</el-button></div>
<el-row :gutter="16" class="st"><el-col :span="6"><el-card><el-statistic title="任务" :value="jobs.length"/></el-card></el-col><el-col :span="6"><el-card><el-statistic title="完成" :value="jobs.filter(j=>j.status==='completed').length"/></el-card></el-col></el-row>
<el-card><template #header><span>训练任务</span></template>
<el-table :data="jobs" stripe v-loading="loading"><el-table-column prop="job_id" label="ID" width="80"/><el-table-column label="环境" width="140"><template #default="{row}">{{row.config?.env||'CartPole'}}</template></el-table-column><el-table-column label="算法" width="140"><template #default="{row}"><el-tag type="success" size="small">{{row.config?.algorithm||'DQN'}}</el-tag></template></el-table-column><el-table-column label="进度" width="180"><template #default="{row}"><el-progress :percentage="row.progress||0" :status="row.status==='completed'?'success':''"/></template></el-table-column><el-table-column label="平均奖励" width="110"><template #default="{row}"><span v-if="row.metrics">{{row.metrics.avg_reward?.toFixed(1)}}</span></template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status==='completed'?'success':'warning'" size="small">{{row.status}}</el-tag></template></el-table-column></el-table></el-card>
<el-dialog v-model="showTrain" title="RL训练" width="500px"><el-form :model="f" label-width="90px"><el-form-item label="环境"><el-select v-model="f.env" style="width:100%"><el-option label="CartPole" value="cartpole"/><el-option label="MountainCar" value="mountain_car"/><el-option label="LunarLander" value="lunar_lander"/></el-select></el-form-item><el-form-item label="算法"><el-select v-model="f.algorithm" style="width:100%"><el-option label="DQN" value="dqn"/><el-option label="PPO" value="ppo"/><el-option label="A2C" value="a2c"/></el-select></el-form-item><el-form-item label="总步数"><el-input-number v-model="f.total_steps" :min="1000" :max="1000000" :step="10000"/></el-form-item></el-form><template #footer><el-button @click="showTrain=false">取消</el-button><el-button type="primary" @click="doTrain" :loading="tl">训练</el-button></template></el-dialog>
</div></template>
<script setup lang="ts">import {ref,onMounted} from 'vue';import {ElMessage} from 'element-plus';import {get,post} from '@/api/legacy';
const loading=ref(false),tl=ref(false),showTrain=ref(false),jobs=ref<any[]>([]),f=ref({env:'cartpole',algorithm:'dqn',total_steps:50000});
onMounted(refreshJobs);async function refreshJobs(){loading.value=true;try{const r=await get('/rl/jobs');jobs.value=r.jobs||[]}catch{}finally{loading.value=false}}
async function doTrain(){tl.value=true;try{await post('/rl/train',f.value);ElMessage.success('RL训练启动');showTrain.value=false;refreshJobs()}catch(e:any){ElMessage.error('失败')}finally{tl.value=false}}</script>
<style scoped>.pg{padding:24px}.hd{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.hd h2{margin:0;font-size:20px}.st{margin-bottom:20px}</style>
